export type WriteOwner = string;

export type OwnerHolder = {
  readonly owner: WriteOwner;
  readonly token: string;
  readonly claimedAt: number;
};

export type OwnerClaim =
  | {
      readonly ok: true;
      readonly owner: WriteOwner;
      readonly token: string;
      readonly reentrant: boolean;
      readonly holder: OwnerHolder;
    }
  | {
      readonly ok: false;
      readonly reason: "conflict";
      readonly holder: OwnerHolder;
    };

export type ReleaseResult =
  | { readonly ok: true; readonly released: true }
  | {
      readonly ok: false;
      readonly reason: "not-owner" | "token-mismatch" | "not-claimed";
    };

export type MutationQueue = {
  run<T>(filePath: string, task: () => Promise<T>): Promise<T>;
};

export type WriteResult<T> =
  | {
      readonly ok: true;
      readonly value: T;
      readonly owner: WriteOwner;
      readonly token: string;
    }
  | {
      readonly ok: false;
      readonly reason: "conflict";
      readonly holder: OwnerHolder;
    };

type InternalHolder = {
  owner: WriteOwner;
  token: string;
  claimedAt: number;
};

let generatedTokenSequence = 0;

function createToken(): string {
  generatedTokenSequence += 1;
  return `${Date.now().toString(36)}-${generatedTokenSequence.toString(36)}-${Math.random()
    .toString(36)
    .slice(2)}`;
}

function copyHolder(holder: InternalHolder): OwnerHolder {
  return {
    owner: holder.owner,
    token: holder.token,
    claimedAt: holder.claimedAt,
  };
}

/**
 * Adds verifiable write ownership in front of the existing per-file mutation
 * queue. The queue remains the only scheduler: this class only performs the
 * synchronous claim/release bookkeeping around calls to that queue.
 */
export class HotFileWriteOwner {
  readonly #holders = new Map<string, InternalHolder>();
  readonly #mutationQueue: MutationQueue;

  constructor(mutationQueue: MutationQueue) {
    this.#mutationQueue = mutationQueue;
  }

  claim(filePath: string, owner: WriteOwner, token?: string): OwnerClaim {
    const current = this.#holders.get(filePath);
    if (current) {
      if (current.owner === owner) {
        return {
          ok: true,
          owner,
          token: current.token,
          reentrant: true,
          holder: copyHolder(current),
        };
      }
      return {
        ok: false,
        reason: "conflict",
        holder: copyHolder(current),
      };
    }

    const next: InternalHolder = {
      owner,
      token: token ?? createToken(),
      claimedAt: Date.now(),
    };
    this.#holders.set(filePath, next);
    return {
      ok: true,
      owner,
      token: next.token,
      reentrant: false,
      holder: copyHolder(next),
    };
  }

  release(filePath: string, owner: WriteOwner, token: string): ReleaseResult {
    const current = this.#holders.get(filePath);
    if (!current) {
      return { ok: false, reason: "not-claimed" };
    }
    if (current.owner !== owner) {
      return { ok: false, reason: "not-owner" };
    }
    if (current.token !== token) {
      return { ok: false, reason: "token-mismatch" };
    }
    this.#holders.delete(filePath);
    return { ok: true, released: true };
  }

  holder(filePath: string): OwnerHolder | null {
    const current = this.#holders.get(filePath);
    return current ? copyHolder(current) : null;
  }

  /**
   * Claims the file, then delegates execution to the existing mutation queue.
   * The claim is always released after the queued operation, including when it
   * throws, so failed writes cannot leak ownership.
   */
  async write<T>(
    filePath: string,
    owner: WriteOwner,
    task: () => Promise<T>,
    token?: string,
  ): Promise<WriteResult<T>> {
    const claim = this.claim(filePath, owner, token);
    if (!claim.ok) {
      return { ok: false, reason: "conflict", holder: claim.holder };
    }

    try {
      const value = await this.#mutationQueue.run(filePath, task);
      return { ok: true, value, owner, token: claim.token };
    } finally {
      this.release(filePath, owner, claim.token);
    }
  }
}

export function createHotFileWriteOwner(mutationQueue: MutationQueue): HotFileWriteOwner {
  return new HotFileWriteOwner(mutationQueue);
}

